package corpus.postfix

class SequenceCounter {
    private var value = 0
    fun next(): Int = value++
}

package corpus.postfix

class MutableCounter(var value: Int) {
    operator fun inc(): MutableCounter {
        value += 1
        return this
    }
}

fun updatedReference(): MutableCounter {
    var counter = MutableCounter(0)
    return counter++
}
